mapper.select:
SELECT r.public_reply_id AS id, r.public_inquiry_id AS inquiry_no, r.content AS body, o.mail_outbox_id, o.status_code AS status, o.last_error AS reason, TO_CHAR(o.updated_at, 'YYYY-MM-DD"T"HH24:MI:SS') AS at, CASE WHEN o.status_code = 'MAIL_PENDING' AND o.updated_at < CAST(SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP) - NUMTODSINTERVAL(#{staleMinutes}, 'MINUTE') THEN 1 ELSE 0 END AS stale FROM public_reply r JOIN mail_outbox o ON o.public_reply_id = r.public_reply_id
r.public_inquiry_id = #{no}
ORDER BY r.public_reply_id
